CREATE TABLE lab_runs(id varchar(80) PRIMARY KEY,policy varchar(16) NOT NULL,price bigint NOT NULL DEFAULT 10000,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE accounts(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL REFERENCES lab_runs,login_id varchar(16) NOT NULL,role varchar(16) NOT NULL,status varchar(16) NOT NULL DEFAULT 'ACTIVE',auth_version bigint NOT NULL DEFAULT 1,UNIQUE(realm_id,login_id));
CREATE TABLE password_credentials(account_id uuid PRIMARY KEY REFERENCES accounts,encoded_hash text NOT NULL);
CREATE TABLE auth_contexts(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,account_id uuid NOT NULL REFERENCES accounts,sid_hash varchar(64) NOT NULL,auth_version bigint NOT NULL,authenticated_at timestamptz NOT NULL,method varchar(32) NOT NULL,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE checkout_intents(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,account_id uuid NOT NULL REFERENCES accounts,is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX default_intent ON checkout_intents(realm_id,account_id) WHERE is_default;
CREATE TABLE orders(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,account_id uuid NOT NULL REFERENCES accounts,checkout_id uuid NOT NULL UNIQUE REFERENCES checkout_intents,product varchar(64) NOT NULL,unit_price bigint NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 10),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 1000000),currency varchar(3) NOT NULL CHECK(currency='KRW'),state varchar(16) NOT NULL DEFAULT 'OPEN',close_intent varchar(24),accepted_payment_id uuid,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL);
CREATE TABLE payment_attempts(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,order_id uuid NOT NULL REFERENCES orders,seq integer NOT NULL,provider_order_id varchar(64) NOT NULL UNIQUE,state varchar(32) NOT NULL DEFAULT 'AUTH_PENDING',state_hash varchar(64) NOT NULL UNIQUE,context_hash varchar(64) NOT NULL,ticket_ciphertext text NOT NULL,auth_until timestamptz NOT NULL,provider_ciphertext text,provider_hash varchar(64),instrument varchar(32),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(order_id,seq));
CREATE UNIQUE INDEX active_attempt ON payment_attempts(order_id) WHERE state IN('AUTH_PENDING','AUTHORIZED','CONFIRM_PENDING','CONFIRMING','UNKNOWN','REVIEW');
CREATE TABLE payments(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,order_id uuid NOT NULL REFERENCES orders,attempt_id uuid NOT NULL REFERENCES payment_attempts,provider_hash varchar(64) NOT NULL UNIQUE,provider_ciphertext text NOT NULL,approved_amount bigint NOT NULL CHECK(approved_amount>0),canceled_amount bigint NOT NULL DEFAULT 0,reserved_amount bigint NOT NULL DEFAULT 0 CHECK(reserved_amount>=0),currency varchar(3) NOT NULL,money_state varchar(32) NOT NULL DEFAULT 'CAPTURED',sync_state varchar(16) NOT NULL DEFAULT 'CURRENT',partial_cancelable boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,approved_at timestamptz NOT NULL,observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),next_audit_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(attempt_id,provider_hash),CHECK(canceled_amount>=0 AND canceled_amount<=approved_amount));
CREATE TABLE payment_operations(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,account_id uuid NOT NULL REFERENCES accounts,order_id uuid NOT NULL REFERENCES orders,attempt_id uuid NOT NULL REFERENCES payment_attempts,payment_id uuid REFERENCES payments,kind varchar(16) NOT NULL,amount bigint NOT NULL CHECK(amount>0),reason varchar(200),request_hmac varchar(64) NOT NULL,provider_key_ciphertext text NOT NULL,state varchar(24) NOT NULL DEFAULT 'PENDING',failure_code varchar(64),transaction_id varchar(80),attempts integer NOT NULL DEFAULT 0,queries integer NOT NULL DEFAULT 0,first_sent_at timestamptz,safe_until timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX one_confirm ON payment_operations(attempt_id) WHERE kind='CONFIRM';
CREATE UNIQUE INDEX one_compensation ON payment_operations(payment_id) WHERE kind='COMPENSATE';
CREATE UNIQUE INDEX one_open_cancel ON payment_operations(payment_id) WHERE kind IN('CANCEL','COMPENSATE') AND state IN('PENDING','IN_FLIGHT','UNKNOWN','REVIEW');
CREATE TABLE idempotency_requests(realm_id varchar(80) NOT NULL,account_id uuid NOT NULL,scope varchar(64) NOT NULL,client_key varchar(80) NOT NULL,request_hmac varchar(64) NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(realm_id,account_id,scope,client_key));
CREATE TABLE cancel_reservations(operation_id uuid PRIMARY KEY REFERENCES payment_operations,payment_id uuid NOT NULL REFERENCES payments,amount bigint NOT NULL CHECK(amount>0),state varchar(24) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE payment_movements(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,payment_id uuid NOT NULL REFERENCES payments,operation_id uuid REFERENCES payment_operations,provider_transaction_id varchar(80) NOT NULL UNIQUE,kind varchar(16) NOT NULL CHECK(kind IN('CAPTURE','CANCEL')),amount bigint NOT NULL CHECK(amount>0),occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE operation_jobs(operation_id uuid PRIMARY KEY REFERENCES payment_operations,next_at timestamptz NOT NULL DEFAULT clock_timestamp(),lease_until timestamptz,lease_token uuid,worker_id varchar(16));
CREATE TABLE webhook_inbox(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,event_id uuid NOT NULL UNIQUE,body_hash varchar(64) NOT NULL,attempt_id uuid NOT NULL,payload jsonb NOT NULL,state varchar(24) NOT NULL DEFAULT 'PENDING',received_at timestamptz NOT NULL DEFAULT clock_timestamp(),next_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE payment_outbox(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,payment_id uuid NOT NULL REFERENCES payments,aggregate_version bigint NOT NULL,event_type varchar(24) NOT NULL,state varchar(16) NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(payment_id,aggregate_version,event_type));
CREATE TABLE projection_inbox(event_id uuid PRIMARY KEY REFERENCES payment_outbox,applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE payment_receipts(payment_id uuid PRIMARY KEY REFERENCES payments,realm_id varchar(80) NOT NULL,amount bigint NOT NULL,canceled bigint NOT NULL,version bigint NOT NULL);
CREATE TABLE reconciliation_cases(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,order_id uuid NOT NULL REFERENCES orders,operation_id uuid,reason varchar(64) NOT NULL,state varchar(24) NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(order_id,operation_id,reason));
CREATE TABLE audit_events(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,event varchar(64) NOT NULL,outcome varchar(64) NOT NULL,actor_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
